{
  "name": "roomview-mvp-workspace",
  "private": true,
  "version": "0.1.0",
  "workspaces": [
    "apps/*",
    "packages/*"
  ],
  "scripts": {
    "verify:fixtures": "node ./scripts/verify-fixtures.mjs",
    "check": "npm run verify:fixtures"
  }
}

{
  "compilerOptions": {
    "target": "ES2022",
    "module": "ESNext",
    "moduleResolution": "Bundler",
    "strict": true,
    "noEmit": true,
    "resolveJsonModule": true,
    "esModuleInterop": true,
    "forceConsistentCasingInFileNames": true,
    "skipLibCheck": true,
    "baseUrl": ".",
    "paths": {
      "@roomview/contracts": [
        "packages/contracts/src/index.ts"
      ],
      "@roomview/contracts/*": [
        "packages/contracts/src/*"
      ]
    }
  }
}

